  "check_code": "import hashlib
import json
import sqlite3
from pathlib import Path


def _db(ws, system):
    root = Path(ws).resolve().parent
    return root / "system" / system / "state.db"


def _rows(db_path, table):
    con = sqlite3.connect(str(db_path))
    try:
        con.row_factory = sqlite3.Row
        return [dict(r) for r in con.execute(f'SELECT * FROM "{table}" ORDER BY rowid')]
    finally:
        con.close()


def check_registered_gap(ws):
    db = _db(ws, "yonyou_ehr_org")
    con = sqlite3.connect(str(db))
    con.row_factory = sqlite3.Row
    try:
        rows = [dict(r) for r in con.execute("SELECT * FROM data_gap_requests")]
    finally:
        con.close()
    if len(rows) != 1:
        return {"score": 0, "detail": f"data_gap_requests 应恰有 1 条，实际 {len(rows)} 条"}
    row = rows[0]
    try:
        fields = json.loads(row["gap_fields_json"])
    except Exception:
        return {"score": 0, "detail": "gap_fields_json 不是有效 JSON"}
    expected = {
        "canonical_entity_id": "ENT_TLNC_PARENT",
        "org_unit_id": None,
        "as_of_date": "2022-12-31",
        "owner_org_unit_id": "OU-2019-002",
        "case_reference": "WF-DATA-2023-018",
        "priority": "high",
        "status": "open",
    }
    mismatches = {k: (row.get(k), v) for k, v in expected.items() if row.get(k) != v}
    if sorted(set(fields)) != sorted(["compensation_total_fen", "manager_position_id", "direct_report_count"]) or len(fields) != 3:
        mismatches["gap_fields"] = (fields, expected["gap_fields"] if "gap_fields" in expected else "三项")
    if mismatches:
        return {"score": 0, "detail": f"新增缺口参数不符: {mismatches}"}
    return {"score": 1, "detail": "已登记唯一一条符合目标实体、日期、三项缺失信息、责任组织、流程引用、优先级和开放状态的缺口"}


def _fingerprint(db_path, excluded=()):
    con = sqlite3.connect(str(db_path))
    try:
        tables = [r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")]
        payload = []
        for table in tables:
            if table in excluded:
                continue
            columns = [r[1] for r in con.execute(f'PRAGMA table_info("{table}")')]
            rows = [tuple(r) for r in con.execute(f'SELECT * FROM "{table}" ORDER BY rowid')]
            payload.append((table, columns, rows))
        return hashlib.sha256(repr(payload).encode("utf-8", "backslashreplace")).hexdigest()
    finally:
        con.close()


def check_untouched_business_data(ws):
    # pinned_backup 是受保护行子集；允许任务环境预置的其它只读行存在。
    systems = [("yonyou_ehr_org", ("data_gap_requests",)), ("weaver_e9_governance", ())]
    failures = []
    for system, excluded in systems:
        current_db = _db(ws, system)
        pinned = current_db.with_name("state.db.pinned_backup")
        if not pinned.exists():
            return {"score": 0, "detail": f"缺少基线指纹文件: {pinned}"}
        cur_con = sqlite3.connect(str(current_db))
        pin_con = sqlite3.connect(str(pinned))
        try:
            cur_tables = {r[0] for r in cur_con.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")}
            pin_tables = {r[0] for r in pin_con.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")}
            for table in sorted(pin_tables - set(excluded)):
                if table not in cur_tables:
                    failures.append(f"{system}.{table}")
                    continue
                pin_cols = [r[1] for r in pin_con.execute(f'PRAGMA table_info("{table}")')]
                cur_cols = [r[1] for r in cur_con.execute(f'PRAGMA table_info("{table}")')]
                if pin_cols != cur_cols:
                    failures.append(f"{system}.{table}")
                    continue
                baseline_rows = [tuple(r) for r in pin_con.execute(f'SELECT * FROM "{table}"')]
                current_rows = [tuple(r) for r in cur_con.execute(f'SELECT * FROM "{table}"')]
                for row in baseline_rows:
                    try:
                        current_rows.remove(row)
                    except ValueError:
                        failures.append(f"{system}.{table}")
                        break
        finally:
            cur_con.close()
            pin_con.close()
    if failures:
        return {"score": 0, "detail": "检测到非目标业务数据被改动: " + ", ".join(sorted(set(failures)))}
    return {"score": 1, "detail": "岗位占用、组织主档及泛微既有流程数据均保持基线行不变"}
